actions.script:
def orgId = ec.user.getPreference('ACTIVE_ORGANIZATION')
// A SaaS account is created in the selected tenant, even if the owner manages several.
def myT = seatCapacity?.tenantGroupId ? [seatCapacity.tenantGroupId] :
    ec.entity.find("moqui.security.UserGroupMember").condition("userId", ec.user.userId).list()*.userGroupId.findAll{ it?.startsWith('TENANT_') }
myT.each { tg -> ec.entity.makeValue("moqui.security.UserGroupMember").setAll([userGroupId:tg, userId:userOut.userId, fromDate:ec.user.nowTimestamp]).create() }
// give the new user the tenant's active organization so row-level filters work on login
if (orgId) {
    ec.entity.makeValue("moqui.security.UserPreference").setAll([userId:userOut.userId, preferenceKey:'ACTIVE_ORGANIZATION', preferenceValue:orgId]).createOrUpdate()
    // ZE-USERS-001: link the new user's PARTY to the org as an Employee (OrgInternal) so they can
    // actually LOG IN with the Org ID. The login org-access check requires a
    // PrtEmployee/PrtAgent/PrtMember relationship to the org — a TENANT_ group + the
    // ACTIVE_ORGANIZATION preference alone is NOT enough (setup#UserOrganizationInfo even STRIPS
    // that preference on login for non-members). Without this, every user created here was
    // locked out on first login ("...your account doesn't have access to it").
    def _npid = ec.entity.find("moqui.security.UserAccount").condition("userId", userOut.userId).one()?.partyId
    if (_npid) {
        ec.entity.makeValue("mantle.party.PartyRole").setAll([partyId:_npid, roleTypeId:'Employee']).createOrUpdate()
        ec.entity.makeValue("mantle.party.PartyRelationship").setAll([relationshipTypeEnumId:'PrtEmployee',
                fromPartyId:_npid, fromRoleTypeId:'Employee', toPartyId:orgId, toRoleTypeId:'OrgInternal',
                fromDate:ec.user.nowTimestamp]).setSequencedIdPrimary().create()
    }
}

def uList
if (ec.user.isInGroup('ADMIN')) {
    uList = ec.entity.find("moqui.security.UserAccount").orderBy("username").list()
} else {
    def myT = ec.entity.find("moqui.security.UserGroupMember").condition("userId", ec.user.userId).list()*.userGroupId.findAll{ it?.startsWith('TENANT_') }
    def ids = [ec.user.userId]
    if (myT) ids = (ec.entity.find("moqui.security.UserGroupMember").condition("userGroupId","in",myT).list()*.userId + [ec.user.userId]).unique()
    uList = ec.entity.find("moqui.security.UserAccount").condition("userId","in",ids).orderBy("username").list()
}
def esc = { v -> def s = (v == null ? "" : v.toString()); (s.contains(",") || s.contains("\"") || s.contains("\n") || s.contains("\r")) ? "\"" + s.replace("\"", "\"\"") + "\"" : s }
def sb = new StringBuilder("Username,Full Name,Status,Assigned Roles\n")
uList.each { u ->
    def roles = ec.entity.find("moqui.security.UserGroupMember").condition("userId", u.userId).conditionDate("fromDate","thruDate",ec.user.nowTimestamp).list()*.userGroupId.findAll { it?.startsWith("ZENITH_") }.unique().sort().join("; ")
    def status = (u.disabled == "Y") ? "Disabled" : "Active"
    sb.append(esc(u.username)).append(",").append(esc(u.userFullName)).append(",").append(status).append(",").append(esc(roles)).append("\n")
}
ec.web.sendTextResponse(sb.toString(), "text/csv;charset=UTF-8", "zenith-users.csv")

if.script:
boolean _d = ec.artifactExecution.disableAuthz()
try {
    def r = ec.service.sync().name("org.moqui.impl.UserServices.update#PasswordInternal")
            .parameters([userId: userId, newPassword: newPassword, newPasswordVerify: newPasswordVerify]).call()
    if (r?.updateSuccessful && !ec.message.hasError()) ec.message.addMessage("Password reset successfully.")
} finally { if (!_d) ec.artifactExecution.enableAuthz() }

boolean _d = ec.artifactExecution.disableAuthz()
try {
    long n = ec.entity.find("moqui.security.UserAuthcFactor").condition("userId", userId).deleteAll()
    if (n > 0) ec.message.addMessage("Two-factor login has been reset. This user can now sign in with just their password and set it up again.")
    else ec.message.addMessage("This user does not have two-factor login set up.")
} finally { if (!_d) ec.artifactExecution.enableAuthz() }

boolean _d = ec.artifactExecution.disableAuthz()
try {
    def ua = ec.entity.find("moqui.security.UserAccount").condition("userId", userId).one()
    if (ua != null) { ua.disabled = "Y"; ua.disabledDateTime = null; ua.update() }
} finally { if (!_d) ec.artifactExecution.enableAuthz() }

actions.script:
// ZE-ROLE-007: honour the column-header sort. The show-order-by arrows submit an orderByField param
// (username / -username / userFullName / -userFullName; "-" = descending), but the manual query
// hardcoded orderBy("username") so clicking did nothing. Whitelist the two sortable columns (both
// directions) to stay injection-safe, and default to username.
def _obf = ec.context.orderByField
if (_obf instanceof List) _obf = _obf ? _obf[-1] : null
def _sortable = ['username','-username','userFullName','-userFullName']
def _ob = _sortable.contains(_obf) ? _obf : 'username'
currentSort = _sortable.contains(_obf) ? _obf : ''   // ZE-ROLE-008: explicit sort, carried by the search form so search+sort combine
if (ec.user.isInGroup('ADMIN')) {
    userList = ec.entity.find("moqui.security.UserAccount").orderBy(_ob).list()
} else {
    def myT = ec.entity.find("moqui.security.UserGroupMember").condition("userId", ec.user.userId).list()*.userGroupId.findAll{ it?.startsWith('TENANT_') }
    def ids = [ec.user.userId]
    if (myT) ids = (ec.entity.find("moqui.security.UserGroupMember").condition("userGroupId","in",myT).list()*.userId + [ec.user.userId]).unique()
    userList = ec.entity.find("moqui.security.UserAccount").condition("userId","in",ids).orderBy(_ob).list()
}
// ZE-ROLE-008: search filter. Match the term (case-insensitive) against username, full name or
// email. Applied in-memory after the org-scoped fetch (the per-tenant user list is small), so the
// org/role scoping above is never widened by the search.
def _st = ec.context.searchTerm
if (_st?.trim()) {
    def _t = _st.trim().toLowerCase()
    userList = userList.findAll {
        (it.username ?: '').toLowerCase().contains(_t) ||
        (it.userFullName ?: '').toLowerCase().contains(_t) ||
        (it.emailAddress ?: '').toLowerCase().contains(_t)
    }
}
// ZE-USERS filter enhancement: status + role filters. Combine with the search + sort and are
// applied IN-MEMORY on the already org-scoped list (so the org/role scoping is never widened),
// and persist in the URL like the search. currentStatus/currentRole echo the active choice back
// to the dropdowns.
def _sf = ec.context.statusFilter
if (_sf instanceof List) _sf = _sf ? _sf[-1] : null
currentStatus = (_sf == 'active' || _sf == 'disabled') ? _sf : ''
if (currentStatus == 'active') userList = userList.findAll { it.disabled != 'Y' }
else if (currentStatus == 'disabled') userList = userList.findAll { it.disabled == 'Y' }
def _rf = ec.context.roleFilter
if (_rf instanceof List) _rf = _rf ? _rf[-1] : null
currentRole = _rf?.trim() ?: ''
if (currentRole) {
    def _roleUsers = ec.entity.find("moqui.security.UserGroupMember")
            .condition("userGroupId", currentRole)
            .conditionDate("fromDate", "thruDate", ec.user.nowTimestamp).list()*.userId as Set
    userList = userList.findAll { _roleUsers.contains(it.userId) }
}

roleNamesById = allRolesList.collectEntries { [(it.userGroupId):it.description] }
def visibleUserIds = userList.collect { it.userId }
def memberships = visibleUserIds ? ec.entity.find('moqui.security.UserGroupMember')
    .condition('userId','in',visibleUserIds).conditionDate('fromDate','thruDate',ec.user.nowTimestamp).list() : []
adminUserIds = memberships.findAll { it.userGroupId in ['ADMIN','ZENITH_ADMIN'] }*.userId as Set
userRolesById = memberships.findAll { roleNamesById.containsKey(it.userGroupId) }
    .unique { it.userId + ':' + it.userGroupId }.groupBy { it.userId }
userRoleIdsById = userRolesById.collectEntries { id, roles -> [(id):roles.collect { it.userGroupId }] }
def shopOrg = ec.user.getPreference('ACTIVE_ORGANIZATION')
userShopIdsById = shopOrg && visibleUserIds ? ec.entity.find('zenith.erp.base.OrganizationUserShopAccess')
    .condition('organizationPartyId',shopOrg).condition('userId','in',visibleUserIds).disableAuthz().list()
    .collectEntries { [(it.userId):new groovy.json.JsonSlurper().parseText(it.shopIdsJson)] } : [:]
usersWithTwoFactor = visibleUserIds ? ec.entity.find('moqui.security.UserAuthcFactor')
    .condition('userId','in',visibleUserIds).disableAuthz().list().collect { it.userId } as Set : [] as Set
